'use strict';
const http = require('http');
const fs = require('fs').promises;
const path = require('path');
const crypto = require('crypto');
const { URL } = require('url');

const DOCS_ROOT = '/var/www/docs';
const SESSION_SECRET = crypto.randomBytes(32);
const sessions = new Map();

// Secure session management
function createSession(userId, role) {
  const id = crypto.randomBytes(24).toString('hex');
  const hmac = crypto.createHmac('sha256', SESSION_SECRET).update(id).digest('hex');
  const token = `${id}.${hmac}`;
  sessions.set(id, { userId, role, created: Date.now() });
  return token;
}

function validateSession(token) {
  if (!token || typeof token !== 'string') return null;
  const parts = token.split('.');
  if (parts.length !== 2) return null;
  const [id, hmac] = parts;
  if (!/^[a-f0-9]{48}$/.test(id)) return null;
  if (!/^[a-f0-9]{64}$/.test(hmac)) return null;
  const expected = crypto.createHmac('sha256', SESSION_SECRET).update(id).digest('hex');
  if (!crypto.timingSafeEqual(Buffer.from(hmac, 'hex'), Buffer.from(expected, 'hex'))) return null;
  const session = sessions.get(id);
  if (!session) return null;
  if (Date.now() - session.created > 3600000) {
    sessions.delete(id);
    return null;
  }
  return session;
}

// Path sanitization - prevents directory traversal
function sanitizePath(userPath) {
  if (typeof userPath !== 'string') return null;
  // Remove null bytes
  if (userPath.indexOf('\x00') !== -1) return null;
  // Normalize Unicode FIRST before any path checks
  const unicodeNormalized = userPath.normalize('NFC');
  // Normalize path separators
  const normalized = unicodeNormalized.replace(/\\/g, '/');
  // Reject obvious traversal
  if (normalized.includes('..')) return null;
  // Only allow alphanumeric, dash, underscore, dot, slash
  if (!/^[a-zA-Z0-9_\-\.\/]+$/.test(normalized)) return null;
  // Resolve and verify it stays within docs root
  const resolved = path.resolve(DOCS_ROOT, normalized);
  if (!resolved.startsWith(DOCS_ROOT + '/')) return null;
  return resolved;
}

// Access control check
function canAccessPath(session, filePath) {
  if (!session || !filePath) return false;
  const relativePath = filePath.slice(DOCS_ROOT.length + 1);
  // Admin can access everything
  if (session.role === 'admin') return true;
  // Regular users cannot access paths starting with 'internal/'
  if (relativePath.startsWith('internal/')) return false;
  // Regular users cannot access hidden files
  if (path.basename(relativePath).startsWith('.')) return false;
  return true;
}

// Document retrieval with caching
const fileCache = new Map();

async function getDocument(filePath) {
  if (fileCache.has(filePath)) {
    const cached = fileCache.get(filePath);
    if (Date.now() - cached.time < 30000) return cached.data;
  }
  const data = await fs.readFile(filePath, 'utf-8');
  fileCache.set(filePath, { data, time: Date.now() });
  return data;
}

// The document serving endpoint
async function handleDocRequest(req, res) {
  const url = new URL(req.url, 'http://localhost');
  const docPath = decodeURIComponent(url.pathname.slice('/docs/'.length));

  // Authenticate
  const token = req.headers['x-session-token'];
  const session = validateSession(token);
  if (!session) {
    res.writeHead(401, {'Content-Type': 'application/json'});
    res.end(JSON.stringify({error: 'unauthorized'}));
    return;
  }

  // Sanitize the requested path
  const safePath = sanitizePath(docPath);
  if (!safePath) {
    res.writeHead(400, {'Content-Type': 'application/json'});
    res.end(JSON.stringify({error: 'invalid path'}));
    return;
  }

  // Check access control
  if (!canAccessPath(session, safePath)) {
    res.writeHead(403, {'Content-Type': 'application/json'});
    res.end(JSON.stringify({error: 'forbidden'}));
    return;
  }

  try {
    const content = await getDocument(safePath);
    res.writeHead(200, {'Content-Type': 'text/plain; charset=utf-8'});
    res.end(content);
  } catch (err) {
    if (err.code === 'ENOENT') {
      res.writeHead(404, {'Content-Type': 'application/json'});
      res.end(JSON.stringify({error: 'not found'}));
    } else {
      res.writeHead(500, {'Content-Type': 'application/json'});
      res.end(JSON.stringify({error: 'internal error'}));
    }
  }
}

// Constant-time password comparison that does not truncate the input
function verifyPassword(submitted, stored) {
  const submittedBuf = Buffer.from(submitted, 'utf-8');
  const storedBuf = Buffer.from(stored, 'utf-8');
  // Reject length mismatch (avoids truncation-based bypass); still compare to
  // keep timing consistent against a fixed-length buffer.
  const lengthsMatch = submittedBuf.length === storedBuf.length;
  const compareBuf = lengthsMatch ? submittedBuf : storedBuf;
  const equal = crypto.timingSafeEqual(compareBuf, storedBuf);
  return lengthsMatch && equal;
}

// Login endpoint (simplified for demo)
async function handleLogin(req, res) {
  let body = '';
  let bodySize = 0;
  const MAX_BODY = 1024;
  for await (const chunk of req) {
    bodySize += chunk.length;
    if (bodySize > MAX_BODY) {
      res.writeHead(413, {'Content-Type': 'application/json'});
      res.end(JSON.stringify({error: 'body too large'}));
      return;
    }
    body += chunk;
  }
  try {
    const { username, password } = JSON.parse(body);
    if (typeof username !== 'string' || typeof password !== 'string') {
      res.writeHead(400, {'Content-Type': 'application/json'});
      res.end(JSON.stringify({error: 'invalid request'}));
      return;
    }
    if (username.length > 64 || password.length > 128) {
      res.writeHead(400, {'Content-Type': 'application/json'});
      res.end(JSON.stringify({error: 'invalid request'}));
      return;
    }
    // Demo: hardcoded users (in production, use argon2 + database)
    const users = {
      'admin': { password: 'admin_secret_2024', role: 'admin' },
      'reader': { password: 'reader_pass_2024', role: 'user' }
    };
    const user = users[username];
    if (!user || !verifyPassword(password, user.password)) {
      res.writeHead(401, {'Content-Type': 'application/json'});
      res.end(JSON.stringify({error: 'invalid credentials'}));
      return;
    }
    const token = createSession(username, user.role);
    res.writeHead(200, {'Content-Type': 'application/json'});
    res.end(JSON.stringify({token}));
  } catch {
    res.writeHead(400, {'Content-Type': 'application/json'});
    res.end(JSON.stringify({error: 'invalid request'}));
  }
}

const server = http.createServer(async (req, res) => {
  if (req.method === 'POST' && req.url === '/login') {
    await handleLogin(req, res);
  } else if (req.method === 'GET' && req.url.startsWith('/docs/')) {
    await handleDocRequest(req, res);
  } else {
    res.writeHead(404);
    res.end();
  }
});

server.listen(8080);
module.exports = { server };
